// Finds the watched URL group by name (case-insensitive) on the owning customer.
const cfg = $('Config').first().json;
const ownerId = cfg.groupOwnerCustomerId || $('Get Partner Self Customer').first().json.id;
const want = String(cfg.urlGroupName || '').trim().toLowerCase();

if (!want || want === 'change_me') {
  throw new Error('Config.urlGroupName is not set. Enter the exact name of the DefensX URL group to watch.');
}
if (!ownerId) {
  throw new Error('Could not resolve the customer that owns the URL group (GET /customers/self returned no id).');
}

const groups = $input.all().map(i => i.json).filter(g => g && g.id !== undefined && g.name);
const matches = groups.filter(g => String(g.name).trim().toLowerCase() === want);

if (matches.length !== 1) {
  const names = groups.map(g => `"${g.name}" (id ${g.id}, public=${g.public})`).join(', ') || 'none returned';
  throw new Error(
    `Expected exactly 1 URL group named "${cfg.urlGroupName}" on customer ${ownerId}, found ${matches.length}. ` +
    `Groups available there: ${names}. If the group lives on a different customer, set Config.groupOwnerCustomerId.`
  );
}

const g = matches[0];
return [{
  json: {
    ownerCustomerId: ownerId,
    groupId: g.id,
    groupName: g.name,
    configType: g.config_type ?? null,
    isPublic: g.public ?? null,
  },
}];

// Turns the group's entries into matchers and stamps the end of this run's log window.
const group = $('Resolve URL Group').first().json;

function parseEntry(value) {
  let s = String(value ?? '').trim().toLowerCase();
  if (!s) return null;
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//, '').replace(/[?#].*$/, '');
  const slash = s.indexOf('/');
  let host = slash === -1 ? s : s.slice(0, slash);
  const path = slash === -1 ? '' : s.slice(slash).replace(/\/+$/, '');
  host = host.replace(/^[^@]*@/, '').replace(/:\d+$/, '').replace(/\.$/, '');
  let wildcard = false;
  if (host.startsWith('*.')) { wildcard = true; host = host.slice(2); }
  host = host.replace(/^www\./, '');
  if (!host) return null;
  return { host, wildcard, path, raw: String(value) };
}

const entries = $input.all()
  .map(i => i.json)
  .filter(e => e && e.value)
  .map(e => parseEntry(e.value))
  .filter(Boolean);

if (entries.length === 0) {
  throw new Error(`URL group "${group.groupName}" (id ${group.groupId}) returned no entries, so nothing can match.`);
}

return [{
  json: {
    ...group,
    entryCount: entries.length,
    entries,
    runEndIso: new Date().toISOString(),
  },
}];

// One item per enabled customer (plus the partner's own "self" customer) with its log window.
// Each customer keeps its own cursor in workflow static data so a failed customer is retried
// from where it left off instead of losing that window.
const cfg = $('Config').first().json;
const ctx = $('Build Run Context').first().json;
const self = $('Get Partner Self Customer').first().json;
const cursors = $getWorkflowStaticData('global').cursors || {};

const overlapMs = Number(cfg.overlapMinutes ?? 5) * 60000;
const firstRunMs = Number(cfg.firstRunLookbackMinutes ?? 20) * 60000;
const maxLookbackMs = Number(cfg.maxLookbackHours ?? 24) * 3600000;
const endMs = Date.parse(ctx.runEndIso);

const seen = new Set();
const out = [];
for (const c of [...$input.all().map(i => i.json), self]) {
  if (!c || !c.id || seen.has(c.id)) continue;
  seen.add(c.id);
  if (c.enabled === false) continue;

  const cursorMs = Date.parse(cursors[c.id] || '');
  const startMs = Number.isFinite(cursorMs)
    ? Math.max(cursorMs - overlapMs, endMs - maxLookbackMs)
    : endMs - firstRunMs;

  out.push({
    json: {
      customerId: c.id,
      customerName: c.name || c.id,
      startIso: new Date(startMs).toISOString(),
      endIso: ctx.runEndIso,
    },
  });
}

if (out.length === 0) throw new Error('GET /customers returned no enabled customers.');
return out;

// Flattens every page of URL logs for the current customer and keeps only blocked rows.
const cfg = $('Config').first().json;
const cust = $('Loop Over Customers').first().json;
const includeConsented = cfg.includeConsented !== false;

const rows = [];
const actionCounts = {};
let scanned = 0;
let error = null;

for (const item of $input.all()) {
  const body = item.json || {};
  if (body.error) {
    error = typeof body.error === 'string' ? body.error : (body.error.message || JSON.stringify(body.error));
    continue;
  }
  for (const r of body.items || []) {
    scanned++;
    const key = `${r.action ?? ''}|${r.sub_type ?? ''}`;
    actionCounts[key] = (actionCounts[key] || 0) + 1;

    const consented = r.sub_type === 'url_block_consented';
    if (consented && !includeConsented) continue;
    if (!consented && !/block/i.test(String(r.action ?? ''))) continue;

    rows.push({
      t: r.created_at,
      userId: r.user_id ?? null,
      agentId: r.agent_id ?? null,
      target: r.url,
      action: r.action ?? null,
      consented,
      categoryKey: r.category_key ?? null,
      riskScore: r.risk_score ?? null,
      src: 'url',
    });
  }
}

return [{ json: { ...cust, urlScanned: scanned, urlActionCounts: actionCounts, urlError: error, urlRows: rows } }];

// Adds DNS-level blocks, keeps only rows whose host/URL is in the watched group,
// and rolls them up to one hit per user + hostname. Always returns exactly one item
// so the loop's "done" output carries a result for every customer.
const ctx = $('Build Run Context').first().json;
const base = $('Collect URL Logs').first().json;

function parseTarget(value) {
  let s = String(value ?? '').trim().toLowerCase();
  if (!s) return null;
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//, '').replace(/[?#].*$/, '');
  const slash = s.indexOf('/');
  let host = slash === -1 ? s : s.slice(0, slash);
  const path = slash === -1 ? '' : s.slice(slash).replace(/\/+$/, '');
  host = host.replace(/^[^@]*@/, '').replace(/:\d+$/, '').replace(/\.$/, '').replace(/^www\./, '');
  return host ? { host, path } : null;
}

function findEntry(target, hasPath) {
  for (const e of ctx.entries) {
    const hostOk = e.wildcard
      ? (target.host === e.host || target.host.endsWith('.' + e.host))
      : target.host === e.host;
    if (!hostOk) continue;
    if (!e.path) return e;
    // Path-scoped entries can only be confirmed against URL logs, not DNS lookups.
    if (hasPath && (target.path === e.path || target.path.startsWith(e.path + '/'))) return e;
  }
  return null;
}

const dnsRows = [];
let dnsScanned = 0;
let dnsError = null;
for (const item of $input.all()) {
  const body = item.json || {};
  if (body.error) {
    dnsError = typeof body.error === 'string' ? body.error : (body.error.message || JSON.stringify(body.error));
    continue;
  }
  for (const r of body.items || []) {
    dnsScanned++;
    // DNS logs only record non-allowed lookups; drop anything explicitly allowed.
    if (/allow|no_action/i.test(String(r.action ?? ''))) continue;
    dnsRows.push({
      t: r.created_at,
      userId: r.user_id ?? null,
      agentId: r.agent_id ?? null,
      target: r.hostname,
      action: r.action ?? null,
      consented: false,
      categoryKey: r.category_key ?? null,
      riskScore: r.risk_score ?? null,
      src: 'dns',
    });
  }
}

const byKey = new Map();
for (const row of [...(base.urlRows || []), ...dnsRows]) {
  const target = parseTarget(row.target);
  if (!target) continue;
  const entry = findEntry(target, row.src === 'url');
  if (!entry) continue;

  const key = `${row.userId || 'unknown'}|${target.host}`;
  let hit = byKey.get(key);
  if (!hit) {
    hit = {
      userId: row.userId,
      agentId: row.agentId,
      hostname: target.host,
      sampleUrl: target.host + target.path, // query string/fragment deliberately dropped
      matchedEntry: entry.raw,
      count: 0,
      firstSeen: row.t,
      lastSeen: row.t,
      sources: [],
      consented: false,
      action: row.action,
      categoryKey: row.categoryKey,
      riskScore: row.riskScore,
    };
    byKey.set(key, hit);
  }
  hit.count++;
  if (row.t && (!hit.firstSeen || row.t < hit.firstSeen)) hit.firstSeen = row.t;
  if (row.t && (!hit.lastSeen || row.t > hit.lastSeen)) hit.lastSeen = row.t;
  if (!hit.sources.includes(row.src)) hit.sources.push(row.src);
  if (row.consented) hit.consented = true;
  if (!hit.agentId && row.agentId) hit.agentId = row.agentId;
}

return [{
  json: {
    customerId: base.customerId,
    customerName: base.customerName,
    startIso: base.startIso,
    endIso: base.endIso,
    ok: !base.urlError,          // URL logs are the primary source; DNS failure is only a warning
    urlError: base.urlError,
    dnsWarning: dnsError,
    urlScanned: base.urlScanned,
    dnsScanned,
    urlActionCounts: base.urlActionCounts,
    hits: [...byKey.values()],
  },
}];

// Runs once after the loop. Drops user+hostname pairs already ticketed inside the
// suppression window, advances the cursor for customers with nothing to report,
// and passes on only customers that need a ticket.
const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');
const cursors = { ...(sd.cursors || {}) };
const notified = { ...(sd.notified || {}) };

const now = Date.now();
const suppressMs = Math.max(Number(cfg.suppressHours ?? 24), 1) * 3600000;
for (const k of Object.keys(notified)) {
  if (now - notified[k] >= suppressMs) delete notified[k];
}

const out = [];
const failures = [];
let okCount = 0;

for (const item of $input.all()) {
  const r = item.json;
  if (!r || !r.customerId) continue;
  if (!r.ok) {
    failures.push(`${r.customerName}: ${r.urlError}`);
    continue; // cursor not advanced -> this window is retried next run
  }
  okCount++;

  const fresh = (r.hits || []).filter(h => !notified[`${r.customerId}|${h.userId || 'unknown'}|${h.hostname}`]);
  if (fresh.length === 0) {
    cursors[r.customerId] = r.endIso;
    continue;
  }
  out.push({ json: { ...r, hits: fresh, suppressedCount: (r.hits || []).length - fresh.length } });
}

sd.cursors = cursors;
sd.notified = notified;

if (okCount === 0 && failures.length > 0) {
  throw new Error(`DefensX URL log fetch failed for every customer (${failures.length}). First error: ${failures[0]}`);
}

return out;

// Resets the SuperOps client accumulator and starts paging at page 1.
const sd = $getWorkflowStaticData('global');
sd.soClients = [];
sd.soPage = 1;
return [{ json: { page: 1 } }];

// Appends this page of SuperOps clients and decides whether another page is needed.
const sd = $getWorkflowStaticData('global');
const page = Number(sd.soPage) || 1;
const res = $input.first().json || {};

if (res.error || res.errors) {
  throw new Error('SuperOps getClientList failed: ' + JSON.stringify(res.error || res.errors).slice(0, 500));
}
const payload = res.data && res.data.getClientList;
if (!payload) {
  throw new Error('SuperOps getClientList returned no data (silent null). Check rate limiting and the CustomerSubDomain header.');
}

const batch = (payload.clients || []).map(c => ({ accountId: c.accountId, name: c.name }));
const all = [...(sd.soClients || []), ...batch];
const total = Number(payload.listInfo && payload.listInfo.totalCount) || 0;
const hasMore = batch.length > 0 && all.length < total && page < 50;

sd.soClients = all;
sd.soPage = page + 1;

return [{ json: { page: page + 1, hasMore, loaded: all.length, total } }];

// One SuperOps ticket per DefensX customer with new hits. Maps the DefensX customer to a
// SuperOps client by normalised name (Config.customerNameMap overrides), resolves user and
// device names, and builds the ticket subject/description.
const cfg = $('Config').first().json;
const ctx = $('Build Run Context').first().json;
const sd = $getWorkflowStaticData('global');
const clients = sd.soClients || [];
sd.soClients = [];   // do not persist the client list between runs
sd.soPage = 1;

const results = $('Collect Results').all().map(i => i.json);
const userResponses = $('Get Users For Hit Customers').all().map(i => i.json);
const agentResponses = $('Get Agents For Hit Customers').all().map(i => i.json);

const TZ = 'America/Los_Angeles';
const defang = cfg.defangUrls !== false;

const norm = s => String(s ?? '')
  .toLowerCase()
  .replace(/&/g, ' and ')
  .replace(/[^a-z0-9 ]+/g, ' ')
  .replace(/\b(inc|incorporated|llc|llp|pllc|ltd|corp|corporation|co|company|pc)\b/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const safeUrl = s => defang ? String(s ?? '').replace(/\./g, '[.]') : String(s ?? '');
const fmt = t => {
  const d = new Date(t);
  return isNaN(d) ? String(t ?? '') : d.toLocaleString('en-US', { timeZone: TZ, dateStyle: 'short', timeStyle: 'short' });
};

let nameMap = {};
try {
  nameMap = typeof cfg.customerNameMap === 'string' ? JSON.parse(cfg.customerNameMap || '{}') : (cfg.customerNameMap || {});
} catch (e) {
  throw new Error('Config.customerNameMap is not valid JSON: ' + e.message);
}
const overrides = new Map(Object.entries(nameMap).map(([k, v]) => [norm(k), norm(v)]));

const byName = new Map();
for (const c of clients) {
  const k = norm(c.name);
  if (!k) continue;
  byName.set(k, byName.has(k) ? null : c); // null = ambiguous, treated as unmapped
}

const out = [];
const unmapped = [];

results.forEach((r, i) => {
  const users = new Map(((userResponses[i] || {}).items || []).map(u => [u.id, u]));
  const agentBody = (agentResponses[i] || {}).body;
  const agents = new Map((Array.isArray(agentBody) ? agentBody : []).map(a => [a.id, a]));

  const wanted = overrides.get(norm(r.customerName)) || norm(r.customerName);
  const client = byName.get(wanted) || null;
  const accountId = client ? client.accountId : (cfg.fallbackSuperOpsAccountId || '');
  if (!client) unmapped.push(r.customerName);
  if (!accountId) return;

  const hits = [...r.hits].sort((a, b) => String(b.lastSeen).localeCompare(String(a.lastSeen)));
  const rowsHtml = hits.map(h => {
    const u = users.get(h.userId);
    const a = agents.get(h.agentId);
    const who = u ? (u.email || u.username || u.name || h.userId) : (h.userId || 'unknown');
    return '<tr>' + [
      esc(fmt(h.lastSeen)),
      esc(who),
      esc(a ? a.hostname : (h.agentId || '')),
      esc(safeUrl(h.sampleUrl)),
      esc(h.count),
      esc(h.sources.join('+') + (h.consented ? ' (user consented past block)' : '')),
      esc(h.categoryKey || ''),
    ].map(c => `<td>${c}</td>`).join('') + '</tr>';
  }).join('');

  const total = hits.reduce((n, h) => n + h.count, 0);
  const userCount = new Set(hits.map(h => h.userId || 'unknown')).size;
  const subject = `DefensX: ${hits.length} blocked site${hits.length === 1 ? '' : 's'} from "${ctx.groupName}" - ${r.customerName}` +
    (client ? '' : ' [UNMAPPED CLIENT]');

  const description =
    `<p>DefensX blocked ${total} request${total === 1 ? '' : 's'} to ${hits.length} site${hits.length === 1 ? '' : 's'} ` +
    `in URL group <b>${esc(ctx.groupName)}</b> for <b>${esc(r.customerName)}</b> (${userCount} user${userCount === 1 ? '' : 's'}).</p>` +
    `<p>Window: ${esc(fmt(r.startIso))} to ${esc(fmt(r.endIso))} Pacific.</p>` +
    (client ? '' : `<p><b>No SuperOps client matched "${esc(r.customerName)}".</b> Filed under the fallback client; add a mapping in the workflow's Config.customerNameMap.</p>`) +
    '<table border="1" cellpadding="4" cellspacing="0"><tr>' +
    ['Last seen', 'User', 'Device', 'Site', 'Blocks', 'Source', 'Category'].map(h => `<th>${h}</th>`).join('') +
    '</tr>' + rowsHtml + '</table>' +
    (defang ? '<p>URLs are defanged ([.]) and query strings removed.</p>' : '<p>Query strings removed.</p>');

  out.push({
    json: {
      customerId: r.customerId,
      customerName: r.customerName,
      endIso: r.endIso,
      mapped: !!client,
      superOpsClientName: client ? client.name : null,
      hitKeys: hits.map(h => `${r.customerId}|${h.userId || 'unknown'}|${h.hostname}`),
      ticketInput: {
        subject,
        description,
        source: 'FORM',
        requestType: cfg.ticketRequestType, // must be one of YOUR tenant's ticket type names
        client: { accountId },
      },
    },
  });
});

if (unmapped.length > 0 && !cfg.fallbackSuperOpsAccountId) {
  throw new Error(
    `No SuperOps client matched DefensX customer(s): ${unmapped.join(', ')}. ` +
    'Set Config.fallbackSuperOpsAccountId or add them to Config.customerNameMap. Nothing was marked as notified, so these hits will be retried.'
  );
}

return out;

// Marks user+hostname pairs as notified and advances the customer's cursor, but only
// for tickets SuperOps actually created. Failed tickets are retried on the next run.
const sd = $getWorkflowStaticData('global');
const cursors = { ...(sd.cursors || {}) };
const notified = { ...(sd.notified || {}) };
const tickets = $('Build Tickets').all().map(i => i.json);
const now = Date.now();

const out = [];

$input.all().forEach((item, i) => {
  const res = item.json || {};
  const t = tickets[i];
  if (!t) return;
  const created = res.data && res.data.createTicket;

  if (created && created.ticketId) {
    for (const k of t.hitKeys) notified[k] = now;
    cursors[t.customerId] = t.endIso;
    out.push({ json: { customerName: t.customerName, status: 'created', ticketId: created.ticketId, displayId: created.displayId ?? null, hits: t.hitKeys.length } });
  } else {
    const reason = JSON.stringify(res.errors || res.error || res).slice(0, 500);
    out.push({ json: { customerName: t.customerName, status: 'failed', reason } });
  }
});

sd.cursors = cursors;
sd.notified = notified;

// No throw here: state written in this node must be kept. The next node raises the failure.
return out;

// Fails the execution (so the error workflow fires) if SuperOps rejected any ticket.
// Kept separate from Record Notified so that node's saved state is never discarded.
const failed = $input.all().map(i => i.json).filter(r => r.status === 'failed');
if (failed.length > 0) {
  throw new Error(
    `SuperOps ticket creation failed for ${failed.length} customer(s): ` +
    failed.map(f => `${f.customerName}: ${f.reason}`).join(' | ')
  );
}
return $input.all();
